window.kbPageData["views/entry/k-2d485314291cd76a"] = {"key":"entry/k-2d485314291cd76a","state":{"route":"entry/k-2d485314291cd76a"},"node":{"id":"k-2d485314291cd76a","mode":"k","title":"莫可名状与不堪言状","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["“莫可名状”与“不堪言状”的词义和感情色彩辨析"],"qs":["江苏 2024 A类 行测#41"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"“莫可名状”指难以用语言形容，可用于复杂微妙的事物。“不堪言状”也有难以形容之意，常用来形容严重或恶劣的情状，带有负面色彩。","review":{"definition":"“莫可名状”指难以用语言形容，可用于复杂微妙的事物。“不堪言状”也有难以形容之意，常用来形容严重或恶劣的情状，带有负面色彩。","explanation":"第41题的提示词工程师既要理解AI逻辑，又涉及法律、宗教、艺术等领域，还要具备产品经理思维。作者在说明这个岗位跨界、难以按传统专业划分，用“莫可名状”贴合难以说清的意思，也契合材料的语气。","references":[],"evidence":"它非文非理、非农非工，既跨界又难以充分量化","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#41":{"paper":"江苏 2024 A类 行测","n":41,"mod":"言语理解与表达","src":["f8fec75f67d6d1ba5759.pdf",8],"asrc":["0126a1c8aceee632ea2b.pdf",13],"card":"4883db28008a5b570d903e2a","links":[{"id":"k-2d485314291cd76a","role":"解题依据","why":"两词都涉及难以形容。“莫可名状”可形容复杂微妙的事物，“不堪言状”常带贬义，辨清这一差异才能判断哪一词契合此处语气。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-2d485314291cd76a":[["江苏 2024 A类 行测#41"]]}};
